    if ep_literal:
        pat += f"\\x01{ep_out}\\x01{RCLASS}\\x01{EPCLASS}"
    else:
        pat += f"\\x01({EPCLASS})\\x01{RCLASS}\\x01{EPCLASS}"
    g_suffix = 2 + nseg
    g_r = {c: 3 + nseg + i for i, c in enumerate("KQkq")}
    g_origep = g_r["q"] + 1 if not ep_literal else None
    newrights = "".join(f"\\g<{g_r[c]}>" for c in "KQkq" if c not in rem)
    origep_re = ep_out if ep_literal else f"\\g<{g_origep}>"
    workep = "-" if ep_literal else ep_out
